mapper.select:
SELECT id, inspection_id, source_version, sku_id, lot_id, result_code, effective_state, command_id, version
FROM quality_qualification
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND inspection_id=#{inspectionId} FOR UPDATE

mapper.update:
UPDATE quality_qualification
SET source_version=#{sourceVersion}, result_code=#{resultCode}, effective_state=#{state}, command_id=#{commandId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND inspection_id=#{inspectionId}
AND source_version<#{sourceVersion}
